INSERT INTO service_categories (code, name, headline, description, need_key, display_order, is_active, created_at, updated_at) VALUES
('TRIAL', 'TRIAL', 'DÙNG THỬ ĐĂNG TIN', 'Trải nghiệm đăng tin tuyển dụng hiệu quả với chi phí tối ưu. Nhà tuyển dụng chỉ được mua và kích hoạt duy nhất 1 gói dùng thử.', NULL, 1, 1, NOW(), NOW()),
('TOP_JOBS', 'TOP JOBS', 'ĐĂNG TIN TUYỂN DỤNG HIỆU SUẤT CAO', 'Cộng hưởng sức mạnh công nghệ tạo ra hiệu quả đột phá cho tin tuyển dụng của doanh nghiệp.', 'REACH', 2, 1, NOW(), NOW()),
('STANDARD', 'STANDARD', 'ĐĂNG TIN TUYỂN DỤNG TIẾT KIỆM', 'Tối ưu chi phí - Tiếp lợi thế cho nhà tuyển dụng.', NULL, 3, 1, NOW(), NOW()),
('CREDIT', 'CREDIT', 'LINH HOẠT SỬ DỤNG CÁC TIỆN ÍCH', 'Sử dụng linh hoạt nhiều tiện ích, hỗ trợ quá trình tuyển dụng, giúp doanh nghiệp có nhiều lựa chọn phù hợp với nhu cầu.', 'CONNECT', 4, 1, NOW(), NOW()),
('ADD_ON', 'ADD-ON', 'DỊCH VỤ CỘNG THÊM', 'Thêm tuỳ chọn giúp tin tuyển dụng nổi bật hơn với ứng viên. Dịch vụ chỉ được áp dụng cho tin đang chạy dịch vụ Top Jobs.', 'HIGHLIGHT', 5, 1, NOW(), NOW()),
('BRANDING', 'EMPLOYER BRANDING', 'TRUYỀN THÔNG THƯƠNG HIỆU TUYỂN DỤNG', 'Xây dựng hình ảnh thương hiệu tuyển dụng uy tín, nâng cao hiệu quả hoạt động tuyển dụng.', 'BRANDING', 6, 1, NOW(), NOW());
INSERT INTO service_packages (category_id, code, slug, name, short_description, price, currency, badge, vip_ribbon, accent_color, validity_days, bonus_credits, one_time_per_company, status, display_order, created_at, updated_at) VALUES
((SELECT id FROM service_categories WHERE code = 'TRIAL'), 'PRO_TRIAL', 'pro-trial', 'PRO TRIAL', 'Trải nghiệm đăng tin tuyển dụng hiệu quả với vị trí ưu tiên trong danh sách việc làm, giá dùng thử hấp dẫn.', 1490000, 'VND', 'NONE', 0, '#16a34a', 14, 50, 1, 'ACTIVE', 1, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'TRIAL'), 'ECO_TRIAL', 'eco-trial', 'ECO TRIAL', 'Trải nghiệm đăng tin tuyển dụng tiết kiệm, kết hợp cùng các dịch vụ khác, giá dùng thử hấp dẫn.', 890000, 'VND', 'NONE', 0, '#16a34a', 14, 30, 1, 'ACTIVE', 2, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'TOP_JOBS'), 'PRO_MAX_PLUS', 'pro-max-plus', 'PRO MAX PLUS', 'Đăng tin tuyển dụng hiệu quả với vị trí nổi bật nhất, x2 lượt đẩy tin, được sử dụng tính năng AI Resume Match và bảo hành đổi tin.', 9650000, 'VND', 'SPECIAL_OFFER', 1, '#2563eb', 30, 0, 0, 'ACTIVE', 1, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'TOP_JOBS'), 'PRO_MAX', 'pro-max', 'PRO MAX', 'Đăng tin tuyển dụng hiệu quả với vị trí nổi bật, được sử dụng tính năng AI Resume Match và nhiều quyền lợi ưu tiên.', 7500000, 'VND', 'NONE', 1, '#16a34a', 30, 0, 0, 'ACTIVE', 2, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'TOP_JOBS'), 'ECO_PLUS', 'eco-plus', 'ECO PLUS', 'Đăng tin tuyển dụng tiết kiệm với vị trí hiển thị ưu tiên, được sử dụng tính năng AI Resume Match.', 4400000, 'VND', 'NONE', 1, '#f59e0b', 30, 0, 0, 'ACTIVE', 3, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'STANDARD'), 'STANDARD_COMBO', 'standard-combo', 'STANDARD COMBO', 'Đăng tin tuyển dụng tiết kiệm với vị trí ưu tiên so với tin cơ bản trên danh sách tìm kiếm việc làm.', 2550000, 'VND', 'NONE', 0, '#16a34a', 30, 0, 0, 'ACTIVE', 1, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'CREDIT'), 'FLEX_BASIC', 'flex-basic', 'FLEX BASIC', 'Linh hoạt sử dụng các tiện ích khác nhau trên nền tảng, từng bước tiếp cận ứng viên phù hợp một cách nhanh chóng nhất.', 6000000, 'VND', 'NONE', 0, '#16a34a', NULL, 0, 0, 'ACTIVE', 1, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'CREDIT'), 'FLEX_PRO', 'flex-pro', 'FLEX PRO', 'Linh hoạt sử dụng các tiện ích khác nhau trên nền tảng với lượng credits lớn hơn, tối ưu chi phí cho nhu cầu tuyển dụng dài hạn.', 8000000, 'VND', 'NONE', 0, '#16a34a', NULL, 0, 0, 'ACTIVE', 2, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'ADD_ON'), 'ADDON_URGENT', 'addon-urgent', 'ADD-ON NHÃN GẤP', 'Tin tuyển dụng được gắn nhãn GẤP vào tiêu đề tin.', 1000000, 'VND', 'NONE', 0, '#dc2626', 7, 0, 0, 'ACTIVE', 1, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'ADD_ON'), 'ADDON_HOT', 'addon-hot', 'ADD-ON NHÃN HOT', 'Tin tuyển dụng được gắn nhãn HOT vào tiêu đề tin.', 1000000, 'VND', 'NONE', 0, '#ea580c', 7, 0, 0, 'ACTIVE', 2, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'ADD_ON'), 'ADDON_HIGHLIGHT', 'addon-highlight', 'ADD-ON TIN NỔI BẬT', 'Tin tuyển dụng hiển thị với nền nổi bật trong danh sách việc làm.', 1200000, 'VND', 'NONE', 0, '#16a34a', 7, 0, 0, 'ACTIVE', 3, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'ADD_ON'), 'ADDON_RETOP', 'addon-retop', 'ADD-ON ĐẨY TOP', 'Tin tuyển dụng được đẩy lên đầu danh sách việc làm 7 lượt.', 1500000, 'VND', 'NONE', 0, '#16a34a', 7, 0, 0, 'ACTIVE', 4, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'ADD_ON'), 'ADDON_AI_MATCH', 'addon-ai-match', 'ADD-ON AI RESUME MATCH', 'Bổ sung 500 lượt phân tích mức độ phù hợp của hồ sơ ứng viên với tin tuyển dụng bằng AI.', 2000000, 'VND', 'NEW', 0, '#2563eb', NULL, 0, 0, 'ACTIVE', 5, NOW(), NOW()),
((SELECT id FROM service_categories WHERE code = 'BRANDING'), 'BRAND_PAGE', 'brand-page', 'BRAND PAGE', 'Nâng cấp trang doanh nghiệp với ảnh bìa, album ảnh, video giới thiệu và ưu tiên xuất hiện trong mục Công ty nổi bật.', 5000000, 'VND', 'NONE', 0, '#16a34a', 30, 0, 0, 'ACTIVE', 1, NOW(), NOW());
